let portfolio=INVESTMENT_DATA;
const variableTypes=new Set(['Ações','Fundos imobiliários','ETFs','Criptomoedas','Outros']);
const iEsc=value=>String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));
