function showInvestmentMessage(text,error=false){const el=document.querySelector('#investmentMessage');el.textContent=text;el.className=`message ${error?'error':'ok'}`;el.hidden=false;setTimeout(()=>el.hidden=true,6500)}
function investmentLabel(item){return item.symbol||item.name}
function renderInvestments(){renderDailySummary();const summary=portfolio.summary||{};document.querySelector('#portfolioCash').textContent=brl(summary.cash_balance||0);document.querySelector('#portfolioWithCash').textContent=brl(summary.total_with_cash??summary.current_value??0);document.querySelector('#portfolioCurrent').textContent=brl(summary.current_value||0);document.querySelector('#portfolioMonthly').textContent=brl(summary.monthly_estimated_gain||0);document.querySelector('#portfolioApplied').textContent=brl(summary.amount_applied||0);const profit=document.querySelector('#portfolioProfit');profit.textContent=brl(summary.profit_loss||0);profit.className=(summary.profit_loss||0)>=0?'positive':'negative';const returned=document.querySelector('#portfolioReturn');returned.textContent=percent(summary.return_percent);returned.className=(summary.return_percent||0)>=0?'positive':'negative';document.querySelector('#investmentUpdated').textContent=`Taxas e cotações: ${formatStamp(portfolio.updated_at)}`;
 const pending=(portfolio.investments||[]).filter(item=>item.calculation_status==='pending_rate'),notice=document.querySelector('#investmentCalculationNotice');notice.hidden=!pending.length;notice.textContent=pending.length?`${pending.length} investimento(s) sem índice de referência. Informe CDI/IPCA na edição ou atualize as taxas.`:'';document.querySelector('#portfolioHistoryTitle').textContent='Ganhos e perdas acumulados';document.querySelector('#portfolioRealized').textContent=`Vendas: ${brl(summary.realized_profit_loss||0)} · Proventos: ${brl(summary.income_received||0)}`;
 const allocation={};(portfolio.investments||[]).filter(investmentIsActive).forEach(item=>allocation[item.type]=(allocation[item.type]||0)+item.current_value);const allocations=Object.entries(allocation).sort((a,b)=>b[1]-a[1]),total=summary.current_value||1;document.querySelector('#investmentAllocation').innerHTML=allocations.length?allocations.map(([name,value],i)=>`<div class="allocation-row"><strong>${iEsc(name)}</strong><div class="track"><div class="fill" style="width:${value/total*100}%;background:${COLORS[i%COLORS.length]}"></div></div><span class="money">${brl(value)}</span></div>`).join(''):'<div class="investment-empty">Cadastre um investimento para visualizar a distribuição.</div>';
 const history=(portfolio.history||[]).map(p=>({...p,current_value:p.profit_loss??p.current_value-p.amount_applied})),svg=document.querySelector('#investmentHistory');if(!history.length){svg.innerHTML='<text x="260" y="95" text-anchor="middle" fill="#687281" font-size="13">Sem histórico para este período.</text>'}else{const values=history.map(x=>x.current_value),min=Math.min(0,...values),max=Math.max(0,...values),spread=max-min||1,points=history.map((x,i)=>`${20+i*480/Math.max(1,history.length-1)},${165-(x.current_value-min)*135/spread}`);svg.innerHTML=`<line class="axis" x1="20" y1="165" x2="500" y2="165"/>${history.length>1?`<path class="area" d="M${points[0]} L${points.join(' L')} L500,165 L20,165 Z"/>`:'<text x="260" y="100" text-anchor="middle" fill="#687281" font-size="12">Primeiro registro. O histórico cresce a cada atualização.</text>'}<polyline class="line" points="${points.join(' ')}"/>${points.map(p=>`<circle class="dot" cx="${p.split(',')[0]}" cy="${p.split(',')[1]}" r="4"><title>${date(history[points.indexOf(p)].date)}: ${brl(history[points.indexOf(p)].current_value)}</title></circle>`).join('')}<text x="20" y="14" fill="#687281" font-size="11">${brl(values.at(-1))}</text><text x="20" y="183" fill="#687281" font-size="10">${date(history[0].date)}</text><text x="500" y="183" text-anchor="end" fill="#687281" font-size="10">${date(history.at(-1).date)}</text>`}
 const filter=document.querySelector('#investmentClassFilter').value;const items=(portfolio.investments||[]).filter(item=>investmentIsActive(item)&&(!filter||(filter==='fixed'?!variableTypes.has(item.type):variableTypes.has(item.type))));document.querySelector('#investmentRows').innerHTML=items.map(item=>{const variable=variableTypes.has(item.type),daily=variable?(item.daily_change_percent!=null?percent(item.daily_change_percent)+'<small>No dia</small>':'—'):(item.monthly_estimated_gain!=null?brl(item.monthly_estimated_gain)+'<small>Estimado / mês</small>':'—'),meta=variable?(item.quote_source||'Manual'):(item.institution||'');return `<tr class="investment-summary-row"><td><button class="expand-investment" data-expand-investment="${item.id}" aria-label="Abrir gráfico de ${iEsc(investmentLabel(item))}" aria-expanded="false">⌄</button></td><td><span class="investment-name"><strong>${iEsc(investmentLabel(item))}</strong><small>${iEsc(meta)}</small>${variable?`<small>${Number(item.remaining_quantity??item.quantity).toLocaleString('pt-BR')} unidade(s) em carteira${item.remaining_quantity===0?' · Posição encerrada':''}</small><small>Vendas: ${brl(item.realized_profit_loss||0)} · Proventos: ${brl(item.income_received||0)}</small>`:''}${variable?'':`<small class="investment-rate-meta">${fixedRateDescription(item)}</small>`}</span></td><td><span class="pill">${variable?'Renda variável':'Renda fixa'}</span>${variable?`<div class="quote-meta">${iEsc(item.type)}</div>`:''}</td><td data-label="Aplicado" class="money">${brl(item.amount_applied)}</td><td data-label="Valor atual" class="money">${brl(item.current_value)}</td><td data-label="Rendimento" class="${(item.daily_change_percent||0)>=0?'positive':'negative'}">${daily}</td><td data-label="Resultado" class="money ${(item.total_profit_loss??item.profit_loss??0)>=0?'positive':'negative'}">${brl(item.total_profit_loss??item.profit_loss)}</td><td data-label="Rentabilidade" class="${(item.total_return_percent??item.return_percent??0)>=0?'positive':'negative'}">${percent(item.total_return_percent??item.return_percent)}</td><td><div class="row-actions">${variable?`<details class="investment-menu"><summary class="secondary">Movimentar <span aria-hidden="true">⌄</span></summary><div class="investment-menu-options"><button type="button" data-add-buy="${item.id}">Novo aporte</button>${item.remaining_quantity>0?`<button type="button" data-sell-investment="${item.id}">Registrar venda</button>`:''}<button type="button" data-add-income="${item.id}">Receber provento</button></div></details>`:`<button type="button" class="secondary" data-redeem-fixed="${item.id}">Registrar resgate</button>`}<button class="secondary" data-edit-investment="${item.id}">Editar</button><button class="danger" data-delete-investment="${item.id}">Excluir</button></div></td></tr><tr class="investment-detail-row" data-investment-detail="${item.id}" hidden><td colspan="9"><div class="asset-detail"><div class="asset-loading">Carregando histórico…</div></div></td></tr>`}).join('');document.querySelector('#investmentEmpty').hidden=!!items.length;renderInvestmentActivity();document.dispatchEvent(new Event('finance-updated'))}
const historyCache=new Map(),chartModes=new Map();
function assetChart(data){
 const variable=variableTypes.has(data.type),points=(data.points||[]).filter(p=>Number.isFinite(Number(variable?p.price:p.value)));
 if(!points.length)return `<div class="investment-empty">Sem dados disponíveis neste período. <button class="secondary" data-retry-history="${data.id}">Ver desde o início</button></div>`;
 const width=900,height=310,left=82,right=20,top=28,bottom=38,plotWidth=width-left-right,plotHeight=height-top-bottom;
 const values=points.map(p=>Number(variable?p.price:p.value)),baseline=Number(variable?data.average_price:data.amount_applied),low=Math.min(...values,baseline),high=Math.max(...values,baseline),margin=(high-low)*.08||Math.max(high*.02,.01),min=low-margin,max=high+margin;
 const y=value=>top+(max-value)/(max-min)*plotHeight,start=Date.parse(points[0].date),end=Date.parse(points.at(-1).date),x=p=>left+(end===start?.5:(Date.parse(p.date)-start)/(end-start))*plotWidth;
 const line=points.map((p,i)=>`${x(p)},${y(values[i])}`).join(' '),last=points.at(-1),change=values[0]?100*(values.at(-1)/values[0]-1):0;
 const ticks=Array.from({length:5},(_,i)=>{const value=min+(max-min)*i/4,py=y(value);return `<line class="chart-grid-line" x1="${left}" y1="${py}" x2="${width-right}" y2="${py}" stroke="#dce7e3"/><text x="${left-9}" y="${py+4}" text-anchor="end">${brl(value)}</text>`}).join('');
 return `<div class="asset-detail-head"><div><strong>${iEsc(data.label)} · ${variable?'Preço por ação / unidade':(data.metric==='gains'?'Ganhos e perdas em R$':(data.metric==='wealth'?'Investimentos + caixa':'Saldo do investimento'))}</strong><span>${iEsc(data.source)} · ${date(last.date)}</span></div><div class="asset-detail-metrics"><span>${variable?'Última cotação':(data.metric==='gains'?'Resultado acumulado':'Último saldo')}<b>${brl(values.at(-1))}</b></span>${data.metric==='gains'?'':`<span>Variação no período<b class="${change>=0?'positive':'negative'}">${percent(change)}</b></span>`}<span>${variable?'Seu preço médio':(data.metric==='gains'?'Referência zero':(data.metric==='wealth'?'Primeiro registro':'Valor aplicado'))}<b>${brl(baseline)}</b></span></div><select class="field history-period" data-history-period="${data.id}" aria-label="Período do gráfico"><option value="all">${data.metric==='gains'?'Desde a aplicação':'Histórico completo'}</option><option value="1m">1 mês</option><option value="3m">3 meses</option><option value="6m">6 meses</option><option value="1y">1 ano</option><option value="5y">5 anos</option></select></div>
 <div class="interactive-asset-chart" tabindex="0" role="group" aria-label="Gráfico interativo de ${iEsc(data.label)}. Use as setas para consultar cada data."><svg class="asset-chart" viewBox="0 0 ${width} ${height}" role="img" aria-label="${variable?'Cotação por unidade':(data.metric==='gains'?'Resultado':'Saldo')} por data">${ticks}<line class="chart-baseline" x1="${left}" y1="${y(baseline)}" x2="${width-right}" y2="${y(baseline)}" stroke="#8b95a5" stroke-dasharray="5 4"/><polyline class="line" points="${line}"/>${points.length===1?`<circle cx="${x(last)}" cy="${y(values[0])}" r="4" fill="#087f5b"/>`:''}<text x="${left}" y="${height-10}">${date(points[0].date)}</text><text x="${width-right}" y="${height-10}" text-anchor="end">${date(last.date)}</text><g class="chart-cursor" visibility="hidden"><line y1="${top}" y2="${height-bottom}" stroke="#68867b" stroke-dasharray="3 3"/><circle r="5" fill="#087f5b" stroke="white" stroke-width="2"/></g></svg><div class="chart-tooltip" hidden aria-live="polite"></div></div>
 <p class="quote-meta">Passe o mouse, toque ou use as setas para consultar a data e ${variable?'o preço de uma unidade. Linha tracejada: seu preço médio.':(data.metric==='gains'?'o lucro ou prejuízo acumulado, incluindo vendas e proventos. Linha tracejada: zero. Sem taxas e impostos.':(data.metric==='wealth'?'o saldo de investimentos e caixa. Linha tracejada: primeiro registro.':'o saldo. Linha tracejada: valor aplicado.'))} ${variable?'Linha de preços de fechamento. Fonte de dados: Yahoo Finance.':(data.metric==='wealth'?'Saldo total da carteira em cada registro. Aportes e retiradas também alteram esse valor.':'Resultado em reais, sem incluir o capital aplicado.')} Sem atualização em tempo real.</p>`;
}
function bindAssetChart(container,data){
 const wrapper=container.querySelector('.interactive-asset-chart');if(!wrapper)return;
 const svg=wrapper.querySelector('svg'),cursor=svg.querySelector('.chart-cursor'),tooltip=wrapper.querySelector('.chart-tooltip'),variable=variableTypes.has(data.type),points=data.points.filter(p=>Number.isFinite(Number(variable?p.price:p.value)));
 const values=points.map(p=>Number(variable?p.price:p.value)),baseline=Number(variable?data.average_price:data.amount_applied),low=Math.min(...values,baseline),high=Math.max(...values,baseline),margin=(high-low)*.08||Math.max(high*.02,.01),min=low-margin,max=high+margin,start=Date.parse(points[0].date),end=Date.parse(points.at(-1).date);let index=points.length-1;
 function show(i){index=Math.max(0,Math.min(points.length-1,i));const point=points[index],x=82+(end===start?.5:(Date.parse(point.date)-start)/(end-start))*798,y=28+(max-values[index])/(max-min)*244;cursor.setAttribute('visibility','visible');const line=cursor.querySelector('line');line.setAttribute('x1',x);line.setAttribute('x2',x);const circle=cursor.querySelector('circle');circle.setAttribute('cx',x);circle.setAttribute('cy',y);tooltip.hidden=false;tooltip.textContent=`${date(point.date)} · ${variable?'Preço por unidade':(data.metric==='gains'?'Resultado':'Saldo')}: ${brl(values[index])}`;if(variable&&point.open!=null)tooltip.textContent+=` · Abertura: ${brl(point.open)} · Máxima: ${brl(point.high)} · Mínima: ${brl(point.low)}${point.volume!=null?' · Volume: '+Number(point.volume).toLocaleString('pt-BR'):''}`;tooltip.style.left=`${Math.min(72,Math.max(2,x/900*100))}%`;}
 wrapper.addEventListener('pointermove',event=>{const matrix=svg.getScreenCTM();if(!matrix)return;const point=svg.createSVGPoint();point.x=event.clientX;point.y=event.clientY;const local=point.matrixTransform(matrix.inverse()),target=start+Math.max(0,Math.min(1,(local.x-82)/798))*(end-start);let nearest=0;points.forEach((p,i)=>{if(Math.abs(Date.parse(p.date)-target)<Math.abs(Date.parse(points[nearest].date)-target))nearest=i});show(nearest)});
 wrapper.addEventListener('pointerleave',()=>{cursor.setAttribute('visibility','hidden');tooltip.hidden=true});
 wrapper.addEventListener('focus',()=>show(index));wrapper.addEventListener('keydown',event=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){event.preventDefault();show(event.key==='Home'?0:event.key==='End'?points.length-1:index+(event.key==='ArrowRight'?1:-1))}});
}
async function loadAssetHistory(id,period='3m'){const container=document.querySelector(`[data-investment-detail="${id}"] .asset-detail`),key=`${id}:${period}`;container.innerHTML='<div class="asset-loading">Carregando histórico…</div>';try{let data=historyCache.get(key);if(!data){const response=await fetch(`/api/investments/${id}/history?period=${period}`,{cache:'no-store'}),result=await response.json();if(!response.ok)throw new Error(result.error||'Histórico indisponível');data=result;historyCache.set(key,data)}const gainMode=chartModes.get(id)==='gains',chartData=gainMode?{...data,type:'Resultado',metric:'gains',amount_applied:0,points:data.gain_points||[]}:data;
container.innerHTML=`<div class="asset-chart-tabs"><button class="secondary" data-chart-mode="market" aria-pressed="${!gainMode}">${variableTypes.has(data.type)?'Cotação da ação':'Saldo do investimento'}</button><button class="secondary" data-chart-mode="gains" aria-pressed="${gainMode}">Meus ganhos e perdas</button></div>`+assetChart(chartData)+salesHistory(data);bindAssetChart(container,chartData);const select=container.querySelector('.history-period');if(select)select.value=period}catch(error){container.innerHTML=`<div class="asset-error">${iEsc(error.message)} <button class="secondary" data-retry-history="${id}">Tentar novamente</button></div>`}}
async function loadInvestments(){if(!canWrite)return;const response=await fetch('/api/investments',{cache:'no-store'}),result=await response.json();if(response.ok){const menuId=document.querySelector('.investment-menu[open] [data-add-buy]')?.dataset.addBuy,opened=document.querySelector('[data-expand-investment][aria-expanded="true"]')?.dataset.expandInvestment,period=opened?document.querySelector(`[data-investment-detail="${opened}"] .history-period`)?.value||'3m':'3m';portfolio=result;historyCache.clear();renderInvestments();if(menuId){const menuButton=document.querySelector(`[data-add-buy="${menuId}"]`);if(menuButton)menuButton.closest('details').open=true}if(opened){const detail=document.querySelector(`[data-investment-detail="${opened}"]`),button=document.querySelector(`[data-expand-investment="${opened}"]`);if(detail&&button){detail.hidden=false;button.setAttribute('aria-expanded','true');await loadAssetHistory(opened,period)}}}}
const investmentModal=document.querySelector('#investmentModal'),investmentForm=document.querySelector('#investmentForm');
function toggleInvestmentFields(){const variable=variableTypes.has(investmentForm.type.value);investmentForm.querySelectorAll('.fixed-field input,.fixed-field select').forEach(input=>input.disabled=variable);investmentForm.querySelectorAll('.variable-field input').forEach(input=>input.disabled=!variable);document.querySelectorAll('.variable-field').forEach(el=>el.classList.toggle('hidden-field',!variable));document.querySelectorAll('.fixed-field').forEach(el=>el.classList.toggle('hidden-field',variable));['symbol','quantity','average_price','purchase_date'].forEach(name=>investmentForm[name].required=variable);['name','institution','amount_invested','application_date','profitability_type','contracted_rate'].forEach(name=>investmentForm[name].required=!variable);updateFixedIncomePreview();updateInvestmentCashPreview();const existing=(portfolio.investments||[]).find(item=>item.id===investmentForm.id.value),locked=!!(existing&&(existing.operation_corrected||existing.sales?.length||existing.buys?.length>1||existing.incomes?.length));investmentForm.type.disabled=locked;['symbol','quantity','average_price','purchase_date'].forEach(name=>investmentForm.elements[name].readOnly=locked)}
function openInvestment(item=null){investmentForm.reset();investmentForm.id.value=item?.id||'';document.querySelector('#investmentFormTitle').textContent=item?'Editar investimento':'Novo investimento';if(item)Object.entries(item).forEach(([key,value])=>{if(investmentForm.elements[key]&&value!=null)investmentForm.elements[key].value=['amount_invested','current_value_manual'].includes(key)?moneyText(value):value});investmentForm.elements.valuation_mode.value=item?.valuation_mode||(item?.current_value_manual!=null?'balance':'automatic');investmentForm.elements.current_value_date.value=item?.current_value_date||item?.updated_at?.slice(0,10)||localDateValue();document.querySelector('#investmentFormMessage').hidden=true;document.querySelector('#ocrPreview').hidden=true;toggleInvestmentFields();investmentModal.hidden=false;investmentForm.elements.type.focus()}
function updateInvestmentCashPreview(){
 const e=investmentForm.elements,preview=document.querySelector('#investmentCashPreview'),existing=(portfolio.investments||[]).find(item=>item.id===e.id.value),balance=portfolio.summary?.cash_balance||0;
 preview.classList.remove('insufficient');
 if(existing&&(existing.operation_corrected||existing.sales?.length||existing.buys?.length>1||existing.incomes?.length)){preview.textContent='As operações deste ativo ficam preservadas. Para movimentar o caixa e a quantidade, use Novo aporte, Registrar venda ou Receber provento.';return}
 if(existing&&existing.cash_funded_amount==null){preview.textContent='Cadastro anterior ao desconto automático. Esta edição mantém o caixa atual.';return}
 const variable=variableTypes.has(e.type.value),raw=variable?Number(e.quantity.value)*Number(e.average_price.value):moneyValue(e.amount_invested.value),cost=Number.isFinite(raw)&&raw>0?Math.round((raw+Number.EPSILON)*100)/100:0,difference=Math.round((cost-(existing?.cash_funded_amount||0))*100)/100,after=Math.round((balance-difference)*100)/100;
 if(!cost){preview.textContent=`Caixa disponível: ${brl(balance)}. O valor aplicado será descontado ao salvar.`;return}
 preview.classList.toggle('insufficient',after<0);preview.textContent=`Caixa atual: ${brl(balance)} · ${difference<0?'Devolver ao caixa':'Descontar do caixa'}: ${brl(Math.abs(difference))} · Após salvar: ${brl(after)}${after<0?' — Saldo insuficiente. Ajuste o caixa antes de salvar.':''}`;
}
