document.querySelector('#extractInvestmentImage').addEventListener('click',()=>{const file=document.querySelector('#investmentImage').files[0],formMessage=document.querySelector('#investmentFormMessage');if(!file){formMessage.textContent='Escolha uma imagem primeiro.';formMessage.className='message error';formMessage.hidden=false;return}const reader=new FileReader();reader.onload=async()=>{try{const response=await fetch('/api/investments/extract-image',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({image:reader.result})}),result=await response.json();if(!response.ok)throw new Error(result.error);Object.entries(result.fields||{}).forEach(([key,value])=>{if(investmentForm.elements[key])investmentForm.elements[key].value=['amount_invested','current_value_manual'].includes(key)?moneyText(value):value});const preview=document.querySelector('#ocrPreview');preview.value=result.text||'Nenhum texto identificado';preview.hidden=false;toggleInvestmentFields();formMessage.textContent='Campos sugeridos pela imagem. Revise todos antes de salvar.';formMessage.className='message ok';formMessage.hidden=false}catch(error){formMessage.textContent=error.message||'Não foi possível ler a imagem.';formMessage.className='message error';formMessage.hidden=false}};reader.readAsDataURL(file)});
function fixedRateDescription(item){
 const status=item.calculation_status;
 if(status==='pending_rate')return item.profitability_type==='CDI'?'Informe o CDI de referência':'Informe o IPCA de referência';
 if(status==='manual')return 'Saldo manual';
 const rate=Number(item.contracted_rate||0).toLocaleString('pt-BR');
 return iEsc(`${item.profitability_type==='CDI'?rate+'% do CDI':item.profitability_type==='IPCA + taxa'?'IPCA + '+rate+'% a.a.':rate+'% '+(item.rate_period==='month'?'a.m.':'a.a.')} · ${status==='matured'?'Vencido':'Automático'}`);
}
function previewAnnualRate(e){
 const rate=Number(e.contracted_rate.value.replace(',','.'))/100,kind=e.profitability_type.value;
 if(!Number.isFinite(rate)||rate<0)return null;
 if(kind==='CDI'){
  if(!e.cdi_rate.value)return null;
  const base=Number(e.cdi_rate.value.replace(',','.'))/100;
  return Math.expm1(252*Math.log1p(Math.expm1(Math.log1p(base)/252)*rate));
 }
 if(kind==='IPCA + taxa')return e.ipca_rate.value?(1+Number(e.ipca_rate.value.replace(',','.'))/100)*(1+rate)-1:null;
 return e.rate_period.value==='month'?Math.expm1(12*Math.log1p(rate)):rate;
}
function updateFixedIncomePreview(){
 const e=investmentForm.elements,variable=variableTypes.has(e.type.value),kind=e.profitability_type.value,mode=e.valuation_mode.value,auto=mode==='automatic',indexed=['CDI','IPCA + taxa'].includes(kind);
 document.querySelector('#investmentRateLabel').textContent=kind==='CDI'?'Percentual do CDI (%)':kind==='IPCA + taxa'?'Taxa acima do IPCA (% ao ano)':'Taxa fixa (%)';
 const fields=[['investmentRatePeriodField',!indexed,'rate_period'],['investmentCdiField',kind==='CDI','cdi_rate'],['investmentIpcaField',kind==='IPCA + taxa','ipca_rate'],['investmentBalanceField',!auto,'current_value_manual'],['investmentBalanceDateField',!auto,'current_value_date']];
 fields.forEach(([id,visible,name])=>{document.querySelector('#'+id).hidden=!visible||variable;e[name].disabled=!visible||variable});
 e.current_value_manual.required=!auto&&!variable;e.current_value_date.required=!auto&&!variable;e.current_value_date.max=localDateValue();
 if(variable)return;
 const preview=document.querySelector('#fixedIncomePreview'),principal=moneyValue(e.amount_invested.value),today=localDateValue(),rate=previewAnnualRate(e),days=(a,b)=>Math.max(0,(Date.parse(a+'T00:00:00Z')-Date.parse(b+'T00:00:00Z'))/86400000);
 if(!principal||!e.application_date.value||!e.contracted_rate.value){preview.textContent='Informe o valor, a data e a taxa.';return}
 if(rate==null&&mode!=='manual'){preview.textContent=kind==='CDI'?'Informe o CDI anual de referência. Você também pode salvar e usar Atualizar taxas.':'Informe o IPCA anual usado na estimativa.';return}
 const end=e.maturity_date.value&&e.maturity_date.value<today?e.maturity_date.value:today,started=today>=e.application_date.value;
 let current=principal;
 if(!auto){
  const balance=moneyValue(e.current_value_manual.value),reference=e.current_value_date.value;
  if(!e.current_value_manual.value||!reference){preview.textContent='Informe o saldo de referência e a data desse saldo.';return}
  if(reference<e.application_date.value||reference>today){preview.textContent='A data do saldo deve ficar entre a aplicação e hoje.';return}
  if(mode==='manual')current=balance;
  else if(end<reference){const elapsed=days(end,e.application_date.value),span=days(reference,e.application_date.value);current=span?principal*Math.pow(balance/principal,elapsed/span):principal}
  else current=balance*Math.exp(Math.log1p(rate)*days(end,reference)/365);
 }else current=principal*Math.exp(Math.log1p(rate)*days(end,e.application_date.value)/365);
 if(!started)current=principal;
 if(!Number.isFinite(current)){preview.textContent='Revise a taxa e as datas.';return}
 const monthly=rate==null?null:Math.expm1(Math.log1p(rate)/12),active=started&&(!e.maturity_date.value||today<e.maturity_date.value);
 preview.innerHTML=`<div><span>Saldo estimado hoje</span><strong>${brl(current)}</strong></div><div><span>Rendimento acumulado</span><strong>${brl(current-principal)}</strong></div>${monthly!=null&&mode!=='manual'?`<div><span>Taxa equivalente ao mês</span><strong>${percent(monthly*100)}</strong></div><div><span>Rendimento mensal estimado</span><strong>${active?brl(current*monthly):'—'}</strong></div>`:'<small>O saldo manual só muda quando você o atualiza.</small>'}${e.maturity_date.value&&today>=e.maturity_date.value?'<small>Rendimento limitado à data de vencimento.</small>':''}`;
}
